package fingerprint

import (
	"context"
	"fmt"

	"github.com/olympus/titan/query"
	"github.com/olympus/titan/sql"
)

type BehavioralEngine struct {
	titanExecutor *query.Executor
}

func NewBehavioralEngine(titan *query.Executor) *BehavioralEngine {
	return &BehavioralEngine{
		titanExecutor: titan,
	}
}

// ComputeAnomalyScore asks TITAN to execute a VECTOR_DISTANCE query
// comparing the current transaction's behavioral vector (generated by ATHENA)
// against the user's historical embedding.
func (be *BehavioralEngine) ComputeAnomalyScore(ctx context.Context, userID string, txn interface{}) (float64, error) {
	// Construct the AST for a Hybrid Query explicitly invoking TITAN.
	// Equivalent to: SELECT VECTOR_DISTANCE(historical_profile, ?) FROM behavioral_profiles WHERE user_id = ?
	
	stmt := &sql.SelectStatement{
		Columns: []sql.Expr{
			&sql.VectorDistanceExpr{
				Vector: &sql.ColumnIdent{Table: "behavioral_profiles", Column: "historical_profile"},
				Query:  "?", // Represents the embedding generated by ATHENA
			},
		},
		From: &sql.TableIdent{Name: "behavioral_profiles"},
		Where: &sql.BinaryExpr{
			Left:     &sql.ColumnIdent{Table: "behavioral_profiles", Column: "user_id"},
			Operator: "=",
			Right:    &sql.StringLiteral{Value: userID},
		},
	}

	// Execute through TITAN
	batch, err := be.titanExecutor.Execute(stmt, query.StrategySQLFirst)
	if err != nil {
		return 0.0, fmt.Errorf("titan execution failed: %w", err)
	}

	if len(batch.Rows) > 0 && len(batch.Rows[0]) > 0 {
		if dist, ok := batch.Rows[0][0].(float64); ok {
			return dist, nil
		}
	}

	// Baseline anomaly
	return 0.0, nil
}
